  function firstObs(seed) {
    const p = trialParameters(seed);
    const rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
    return {
      pos: { x: TAKEOFF.x + p.offset.x + noise(TASK.positionNoise), y: TASK.bodyHeight + noise(TASK.positionNoise), z: TAKEOFF.z + p.offset.z + noise(TASK.positionNoise) },
      vel: { x: noise(TASK.velocityNoise), y: noise(TASK.velocityNoise), z: noise(TASK.velocityNoise) }
    };
  }

  function findSeed(obs, maxSeed) {
    // offset.x is in [obs.pos.x - TAKEOFF.x - 0.0015, obs.pos.x - TAKEOFF.x + 0.0015]
    // offset.x = -0.045 + 0.09 * r1 => r1 = (offset.x + 0.045) / 0.09
    const r1Center = (obs.pos.x - TAKEOFF.x + 0.045) / 0.09;
    const r2Center = (obs.pos.z - TAKEOFF.z + 0.045) / 0.09;
    const halfSpan = (0.00151 / 0.09);
    const u1Min = Math.max(0, Math.floor((r1Center - halfSpan) * 4294967296)) >>> 0;
    const u1Span = Math.ceil(2 * halfSpan * 4294967296) >>> 0;
    const u2Min = Math.max(0, Math.floor((r2Center - halfSpan) * 4294967296)) >>> 0;
    const u2Span = Math.ceil(2 * halfSpan * 4294967296) >>> 0;

    for (let s = 0; s <= maxSeed; s++) {
      let a = (s + 0x6d2b79f5) >>> 0;
      let t = Math.imul(a ^ (a >>> 15), a | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      const u1 = (t ^ (t >>> 14)) >>> 0;
      if (((u1 - u1Min) >>> 0) <= u1Span) {
        a = (a + 0x6d2b79f5) >>> 0;
        t = Math.imul(a ^ (a >>> 15), a | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        const u2 = (t ^ (t >>> 14)) >>> 0;
        if (((u2 - u2Min) >>> 0) <= u2Span) {
