        estPos.z += estVel.z * DT + 0.65 * (obs.pos.z - (estPos.z + estVel.z * DT));
        prevEstVel.x = estVel.x;
        prevEstVel.y = estVel.y;
        prevEstVel.z = estVel.z;
        estVel.x = 0.55 * estVel.x + 0.45 * obs.vel.x;
        estVel.y = 0.55 * estVel.y + 0.45 * obs.vel.y;
        estVel.z = 0.55 * estVel.z + 0.45 * obs.vel.z;
