      const intGainY = knownParams ? 2.2 : 3.2;

      const axDes = clamp(kdX * (vCmdX - v.x) + intGainXZ * integralX, -4.2, 4.2);
      const azDes = clamp(kdZ * (vCmdZ - v.z) + intGainXZ * integralZ, -4.2, 4.2);
      const ayDes = clamp(kdY * (vCmdY - v.y) + intGainY * integralY, -4.0, 5.0);

