      filtDesRoll += (desRoll - filtDesRoll) * (DT / 0.16);
      filtDesPitch += (desPitch - filtDesPitch) * (DT / 0.16);
      if (p.y > 0.12) {
        attTrimRoll = clamp(attTrimRoll + 0.8 * (filtDesRoll - att.roll) * DT, -0.22, 0.22);
        attTrimPitch = clamp(attTrimPitch + 0.8 * (filtDesPitch - att.pitch) * DT, -0.22, 0.22);
