      const vCmdZ = clamp(desVz + (kpZ / kdZ) * ez, -1.55, 1.55);
      const vCmdY = clamp(desVy + (kpY / kdY) * ey, -1.15, 1.45);

      const axDes = clamp(kdX * (vCmdX - v.x) + 2.5 * integralX, -4.5, 4.5);
      const azDes = clamp(kdZ * (vCmdZ - v.z) + 3.0 * integralZ, -4.5, 4.5);
