      const cmdPitch = clamp(desPitch + attTrimPitch - 0.08 * rates.pitch, -0.6, 0.6);

      const actualTiltCos = Math.max(0.65, dirY);
      const reqSpecificThrust = reqAy / actualTiltCos;
      const thrust = clamp(reqSpecificThrust / estKT, 0, 1);
      const yawRate = clamp(-2.0 * att.yaw, -2, 2);

      const act = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate };
      lastAction = act;
      return act;
    },
  };
}
