      const target = clamp(desired, 0, MAX_THRUST) * scale;
      const f = state.motors[i] + (target - state.motors[i]) * alpha;
      state.motors[i] = f;
      sum += f;
      mZ += f * MOTOR_Z[i];
      mX += f * MOTOR_X[i];
      mSpin += f * SPIN[i];
