    let wx = 0, wz = 0;
    for (let k = 0; k < offsets.length; k++) {
      const tk = t + offsets[k];
      let gkx = params.baseWind.x;
      let gkz = params.baseWind.z;
      for (let i = 0; i < params.gusts.length; i++) {
