            estMass = clamp((16 * 0.92) / estKT, 0.6, 0.95);
          }
        }
        const aThrust = knownParams ? (16 / mass) * filtThrust : estKT * filtThrust;
        const rawWxAcc = measAx - (aThrust * dirX - (DRAG / mass) * v.x);
        const rawWzAcc = measAz - (aThrust * dirZ - (DRAG / mass) * v.z);
        windAccX = 0.82 * windAccX + 0.18 * clamp(rawWxAcc, -12, 12);
        windAccZ = 0.82 * windAccZ + 0.18 * clamp(rawWzAcc, -12, 12);
        slowWindAccX = 0.95 * slowWindAccX + 0.05 * windAccX;
        slowWindAccZ = 0.95 * slowWindAccZ + 0.05 * windAccZ;
      }

      if (obs.gateIndex !== currentGateIdx) {
        if (currentGateIdx < 3) {
          prevGateX = GATES[currentGateIdx].x;
          prevGateY = GATES[currentGateIdx].y;
          prevGateZ = GATES[currentGateIdx].z;
        }
        currentGateIdx = obs.gateIndex;
        phase = 'post_cross';
        alignCount = 0;
        integralX = 0;
        integralZ = 0;
      }

      let targetX = p.x, targetY = p.y, targetZ = p.z;
      let desVx = 0, desVy = 0, desVz = 0;
      let kLinX = 2.1, kdX = 5.8, vMaxX = 1.25, aBrakeX = 1.5;
      let kLinZ = 2.6, kdZ = 6.6, vMaxZ = 1.65, aBrakeZ = 2.2;
      let kLinY = 2.4, kdY = 5.8, vMaxY = 1.35, aBrakeY = 2.0;
      let maxTilt = 0.52;

      if (obs.gateIndex < 3) {
        const gate = GATES[obs.gateIndex];
        if (phase === 'post_cross') {
          targetX = prevGateX + 0.22;
          targetY = prevGateY + 0.35 * (gate.y - prevGateY);
          targetZ = prevGateZ;
          desVx = 0.9;
          if (p.x > prevGateX + 0.15) {
            phase = 'align';
            alignCount = 0;
          }
        }

        if (phase === 'align') {
          const errZ = Math.abs(gate.z - p.z);
          const errY = Math.abs(gate.y - p.y);
          // Stay further back in X while Z or Y is still far from the gate opening
          const stageDist = clamp(0.22 + 0.70 * errZ + 0.25 * errY, 0.22, 0.55);
          targetX = gate.x - stageDist;
          targetY = gate.y;
          targetZ = gate.z;

          if (p.x > gate.x - 0.12 && (errZ > 0.023 || errY > 0.09)) {
            targetX = gate.x - 0.28;
            kLinX = 2.6;
          }

          const readyX = p.x > gate.x - 0.35 && p.x < gate.x - 0.03 && Math.abs(v.x) < 0.50;
          const readyZ = errZ < 0.020 && Math.abs(v.z) < 0.11;
          const readyY = errY < 0.085 && Math.abs(v.y) < 0.32;
          const safeWind = !isGustTransitionSoon(obs.t, knownParams) || obs.t > 11.2;

          if (readyX && readyZ && readyY && safeWind) {
            alignCount++;
          } else {
            alignCount = Math.max(0, alignCount - 1);
          }
          if (alignCount >= 2) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const errZ = Math.abs(gate.z - p.z);
          const errY = Math.abs(gate.y - p.y);
          if (p.x < gate.x - 0.06 && (errZ > 0.028 || errY > 0.11)) {
            phase = 'align';
            alignCount = 0;
            targetX = gate.x - 0.26;
            targetY = gate.y;
            targetZ = gate.z;
          } else {
            targetX = gate.x + 0.30;
            targetY = gate.y;
            targetZ = gate.z;
            desVx = 1.0;
            kLinZ = 3.0;
            kdZ = 7.2;
          }
        }
      } else {
        if (phase === 'post_cross') {
          targetX = prevGateX + 0.18;
          targetY = prevGateY;
          targetZ = prevGateZ;
          desVx = 0.85;
          if (p.x > prevGateX + 0.13) {
            phase = 'pad_approach';
          }
        }
        const distPad = Math.hypot(PAD.x - p.x, PAD.z - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (phase === 'pad_approach' || phase === 'align') {
          targetX = PAD.x;
          targetZ = PAD.z;
          targetY = clamp(0.14 + 0.60 * distPad, 0.14, 1.05);
          if (distPad < 0.12 && speedHoriz < 0.35 && p.y < 0.28) {
            phase = 'pad_descend';
          }
        }

        if (phase === 'pad_descend') {
          targetX = PAD.x;
          targetZ = PAD.z;
          targetY = BODY_H;
          desVy = -0.30;
          maxTilt = 0.15;
          if (distPad > 0.145) {
            phase = 'pad_approach';
          } else if (p.y <= BODY_H + 0.015 && distPad < 0.125 && speedHoriz < 0.40) {
            phase = 'pad_hold';
          }
        }

        if (phase === 'pad_hold') {
          if (distPad > 0.138) {
            phase = 'pad_approach';
          } else {
            const cmdRollHold = clamp(-0.20 * att.roll, -0.10, 0.10);
            const cmdPitchHold = clamp(-0.20 * att.pitch, -0.10, 0.10);
            const act = { thrust: 0, roll: cmdRollHold, pitch: cmdPitchHold, yawRate: clamp(-2 * att.yaw, -2, 2) };
            lastAction = act;
            return act;
          }
        }
      }

      const ex = targetX - p.x;
      const ey = targetY - p.y;
      const ez = targetZ - p.z;

      if (Math.abs(ex) < 0.18) integralX = clamp(integralX + ex * DT, -0.25, 0.25);
      else integralX *= 0.92;

      if (Math.abs(ez) < 0.18) integralZ = clamp(integralZ + ez * DT, -0.25, 0.25);
      else integralZ *= 0.92;

      if (Math.abs(ey) < 0.22) integralY = clamp(integralY + ey * DT, -0.35, 0.45);
      else integralY *= 0.94;

      const vCmdX = clamp(desVx + smoothVelCmd(ex, kLinX, vMaxX, aBrakeX), -1.6, 1.6);
      const vCmdZ = clamp(desVz + smoothVelCmd(ez, kLinZ, vMaxZ, aBrakeZ), -1.7, 1.7);
      const vCmdY = clamp(desVy + smoothVelCmd(ey, kLinY, vMaxY, aBrakeY), -1.2, 1.5);

      const axDes = clamp(kdX * (vCmdX - v.x) + 4.5 * integralX, -4.5, 4.5);
      const azDes = clamp(kdZ * (vCmdZ - v.z) + 5.5 * integralZ, -4.5, 4.5);
      const ayDes = clamp(kdY * (vCmdY - v.y) + 4.0 * integralY, -4.0, 5.2);

      let ffWxAcc = windAccX;
      let ffWzAcc = windAccZ;
      if (knownParams) {
        const pw = getPreviewWind(obs.t, knownParams);
        ffWxAcc = (DRAG / mass) * pw.x;
        ffWzAcc = (DRAG / mass) * pw.z;
      }

      const reqAx = axDes + (DRAG / mass) * v.x - ffWxAcc;
      const reqAy = Math.max(2.0, ayDes + G + (DRAG / mass) * v.y);
      const reqAz = azDes + (DRAG / mass) * v.z - ffWzAcc;

      const normA = Math.hypot(reqAx, reqAy, reqAz);
      const ux = reqAx / normA;
      const uy = reqAy / normA;
      const uz = reqAz / normA;

      const desBodyX = cy * ux - sy * uz;
      const desBodyZ = sy * ux + cy * uz;

      const desRoll = clamp(-Math.asin(clamp(desBodyZ, -0.95, 0.95)), -maxTilt, maxTilt);
      const desPitch = clamp(Math.atan2(desBodyX, uy), -maxTilt, maxTilt);

      const actualTiltCos = Math.max(0.60, dirY);
      const reqSpecificThrust = reqAy / actualTiltCos;

      let thrust, cmdRoll, cmdPitch, yawRate;
      if (knownParams && simState) {
        const inertia = INERTIA_BASE * mass / BASE_MASS;
        const baseThrust = clamp((mass * reqSpecificThrust) / 16, 0, 1);
        const w = knownParams.weakness;
        const wm = knownParams.weakMotor;
        const fkStar = baseThrust * MAX_THRUST;
        const deltaK = (w / (1 - w)) * fkStar;

        const dThrust = deltaK / 16;
        const dTorqueRoll = ARM * deltaK * MOTOR_Z[wm];
        const dTorquePitch = -ARM * deltaK * MOTOR_X[wm];
        const dTorqueYaw = YAW_COEFF * deltaK * SPIN[wm];

        // Subtract (22/65)*simState.integral so inner integral does not double-count dTorque
        const dRollCmd = dTorqueRoll / (65 * inertia) - (22 / 65) * simState.integral.roll;
        const dPitchCmd = dTorquePitch / (65 * inertia) - (22 / 65) * simState.integral.pitch;
        const dYawRateCmd = dTorqueYaw / (8 * inertia);

        thrust = clamp(baseThrust + dThrust, 0, 1);
        cmdRoll = clamp(desRoll + dRollCmd - 0.06 * rates.roll, -0.6, 0.6);
        cmdPitch = clamp(desPitch + dPitchCmd - 0.06 * rates.pitch, -0.6, 0.6);
        yawRate = clamp(-2.0 * att.yaw + dYawRateCmd, -2, 2);
      } else {
        filtDesRoll += (desRoll - filtDesRoll) * (DT / 0.16);
        filtDesPitch += (desPitch - filtDesPitch) * (DT / 0.16);
        if (p.y > 0.12) {
          attTrimRoll = clamp(attTrimRoll + 1.0 * (filtDesRoll - att.roll) * DT, -0.24, 0.24);
          attTrimPitch = clamp(attTrimPitch + 1.0 * (filtDesPitch - att.pitch) * DT, -0.24, 0.24);
        }
        thrust = clamp(reqSpecificThrust / estKT, 0, 1);
        cmdRoll = clamp(desRoll + attTrimRoll - 0.08 * rates.roll, -0.6, 0.6);
        cmdPitch = clamp(desPitch + attTrimPitch - 0.08 * rates.pitch, -0.6, 0.6);
        yawRate = clamp(-2.0 * att.yaw, -2, 2);
      }

      const act = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate };
      lastAction = act;
      return act;
    },
  };
}
