    rates.roll += (ARM * mZ / inertia - 0.4 * rates.roll) * dt;
    rates.pitch += (-ARM * mX / inertia - 0.4 * rates.pitch) * dt;
    rates.yaw += (YAW_COEFF * mSpin / inertia - 0.4 * rates.yaw) * dt;
