    const absE = Math.abs(err);
    const sign = err >= 0 ? 1 : -1;
    const vLin = kLin * absE;
    const switchDist = (2 * aBrake) / (kLin * kLin);
    const vProfile = absE <= switchDist
      ? vLin
      : Math.sqrt(2 * aBrake * absE - aBrake * switchDist);
    return sign * Math.min(vMax, vProfile);
  }

