          targetY = prevGateY + 0.35 * (gate.y - prevGateY);
          targetZ = prevGateZ;
          desVx = 0.9;
          if (p.x > prevGateX + 0.15) {
            phase = 'align';
            alignCount = 0;
          }
        }

        if (phase === 'align') {
          const errZ = Math.abs(gate.z - p.z);
          const errY = Math.abs(gate.y - p.y);
          const stageDist = clamp(0.22 + 0.70 * errZ + 0.25 * errY, 0.22, 0.55);
          targetX = gate.x - stageDist;
          targetY = gate.y;
          targetZ = gate.z;

          if (p.x > gate.x - 0.12 && (errZ > 0.023 || errY > 0.09)) {
            targetX = gate.x - 0.28;
            kLinX = 2.6;
          }

          const readyX = p.x > gate.x - 0.35 && p.x < gate.x - 0.03 && Math.abs(v.x) < 0.50;
          const readyZ = errZ < 0.020 && Math.abs(v.z) < 0.11;
          const readyY = errY < 0.085 && Math.abs(v.y) < 0.32;
          const safeWind = !isGustTransitionSoon(obs.t, knownParams) || obs.t > 11.2;

          if (readyX && readyZ && readyY && safeWind) {
