          } else {
            alignCount = Math.max(0, alignCount - 1);
          }
          if (alignCount >= 2) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const errZ = Math.abs(gate.z - p.z);
          const errY = Math.abs(gate.y - p.y);
          if (p.x < gate.x - 0.06 && (errZ > 0.028 || errY > 0.11)) {
            phase = 'align';
            alignCount = 0;
            targetX = gate.x - 0.26;
            targetY = gate.y;
            targetZ = gate.z;
          } else {
            targetX = gate.x + 0.30;
            targetY = gate.y;
            targetZ = gate.z;
