      } else {
        if (phase === 'post_cross') {
          targetX = prevGateX + 0.18;
          targetY = prevGateY;
          targetZ = prevGateZ;
          desVx = 0.85;
          if (p.x > prevGateX + 0.13) {
            phase = 'pad_approach';
          }
