    if (state.pos.y <= BODY_H) {
      state.pos.y = BODY_H;
      state.vel.y = Math.max(0, state.vel.y);
      const decay = Math.exp(-12 * dt);
      state.vel.x *= decay;
      state.vel.z *= decay;
