    for (let i = 0; i < params.gusts.length; i++) {
      const g = params.gusts[i];
      const gEnd = g.start + g.duration;
      if (t >= g.start - 0.14 && t <= g.start + 0.18) return true;
      if (t >= gEnd - 0.14 && t <= gEnd + 0.18) return true;
