  }

  function makeSimState(params) {
    return {
      t: 0,
      pos: { x: TAKEOFF_X + params.offset.x, y: BODY_H, z: TAKEOFF_Z + params.offset.z },
      vel: { x: 0, y: 0, z: 0 },
      att: { roll: 0, pitch: 0, yaw: 0 },
      rates: { roll: 0, pitch: 0, yaw: 0 },
      motors: [0, 0, 0, 0],
      integral: { roll: 0, pitch: 0 },
