        const aThrust = knownParams ? (16 / mass) * filtThrust : estKT * filtThrust;
        const rawWxAcc = measAx - (aThrust * dirX - (DRAG / mass) * v.x);
        const rawWzAcc = measAz - (aThrust * dirZ - (DRAG / mass) * v.z);
        windAccX = 0.82 * windAccX + 0.18 * clamp(rawWxAcc, -12, 12);
        windAccZ = 0.82 * windAccZ + 0.18 * clamp(rawWzAcc, -12, 12);
        slowWindAccX = 0.95 * slowWindAccX + 0.05 * windAccX;
        slowWindAccZ = 0.95 * slowWindAccZ + 0.05 * windAccZ;
      }

      if (obs.gateIndex !== currentGateIdx) {
        if (currentGateIdx < 3) {
          prevGateX = GATES[currentGateIdx].x;
          prevGateY = GATES[currentGateIdx].y;
          prevGateZ = GATES[currentGateIdx].z;
        }
        currentGateIdx = obs.gateIndex;
        phase = 'post_cross';
        alignCount = 0;
      }

      let targetX = p.x, targetY = p.y, targetZ = p.z;
      let desVx = 0, desVy = 0, desVz = 0;
      let kpX = 6.2, kdX = 4.4;
      let kpZ = 7.4, kdZ = 4.8;
      let kpY = 6.8, kdY = 4.4;
      let maxTilt = 0.52;

      if (obs.gateIndex < 3) {
        const gate = GATES[obs.gateIndex];
        if (phase === 'post_cross') {
          targetX = prevGateX + 0.22;
          targetY = prevGateY + 0.4 * (gate.y - prevGateY);
          targetZ = prevGateZ;
          desVx = 0.95;
          if (p.x > prevGateX + 0.14) {
            phase = 'align';
            alignCount = 0;
          }
        }

        if (phase === 'align') {
          const errZ = Math.abs(gate.z - p.z);
          const errY = Math.abs(gate.y - p.y);
          const stageDist = clamp(0.20 + 0.55 * errZ + 0.20 * errY, 0.20, 0.48);
          targetX = gate.x - stageDist;
          targetY = gate.y;
          targetZ = gate.z;

          if (p.x > gate.x - 0.10 && (errZ > 0.023 || errY > 0.09)) {
            targetX = gate.x - 0.26;
            kpX = 7.5;
