          const readyX = p.x > gate.x - 0.36 && p.x < gate.x - 0.02 && Math.abs(v.x) < 0.55;
          const readyZ = errZ < 0.022 && Math.abs(v.z) < 0.12;
          const readyY = errY < 0.09 && Math.abs(v.y) < 0.35;
          const safeWind = !isGustTransitionSoon(obs.t, knownParams) || obs.t > 11.2;

