    maxVx = 1.50;
    if (p.x > 2.25 && v.x > 0.3) {
      kpX = 8.5;
      kdX = 6.0;
    }
    const minApproachY = highWindOnPad ? 0.22 : 0.10;
    targetY = clamp(minApproachY + 0.50 * distPad, minApproachY, 1.00);
    if (!highWindOnPad && distPad < 0.130 && speedHoriz < 0.36 && p.y < 0.23) {
      phase = 'pad_descend';
      integralY = 0;
    }
  }
